===== OwnerAddress =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Map;

/**
 * Normalizes an owner {@code address} to a canonical form. Surrounding and repeated internal
 * whitespace is trimmed and collapsed to a single space, the value is upper-cased, and common
 * street-type abbreviations are expanded as whole words: {@code ST -> STREET}, {@code RD -> ROAD},
 * {@code AVE -> AVENUE}. So {@code '  12  main  st '} becomes {@code '12 MAIN STREET'} and
 * {@code '7 elm ave'} becomes {@code '7 ELM AVENUE'}. A null or whitespace-only value normalizes to
 * the empty string. The normalized value is what is stored, returned, and compared — for the
 * required-field check, household duplicate detection and the shared household id.
 */
final class OwnerAddress {

    /** Whole-word street-type abbreviations expanded to their full form. */
    private static final Map<String, String> ABBREVIATIONS = Map.of(
            "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");

    private OwnerAddress() {
    }

    /**
     * @return the address trimmed, whitespace-collapsed, upper-cased and with abbreviations
     *         expanded, or the empty string when the value is null or blank.
     */
    static String normalize(String address) {
        if (address == null) {
            return "";
        }
        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
        if (collapsed.isEmpty()) {
            return "";
        }
        String[] tokens = collapsed.split(" ");
        StringBuilder sb = new StringBuilder(collapsed.length());
        for (int i = 0; i < tokens.length; i++) {
            if (i > 0) {
                sb.append(' ');
            }
            sb.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
        }
        return sb.toString();
    }
}
===== Postcode =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.regex.Pattern;

import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;

/**
 * Validates the optional owner {@code postcode}. Postcode is absent when null or blank; when present it
 * must be a 4-digit value and, when the city maps to a known region, fall within that region's fixed
 * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit
 * postcode. The postcode is stored and returned as given (trimmed).
 */
final class Postcode {

    private static final Pattern FOUR_DIGITS = Pattern.compile("^[0-9]{4}$");

    private Postcode() {
    }

    /**
     * @return the trimmed postcode, or {@code null} when it is absent (null or blank).
     * @throws InvalidPostcodeException when present but not a 4-digit value, or out of range for the
     *         city's region.
     */
    static String normalize(String postcode, String city) throws InvalidPostcodeException {
        if (postcode == null || postcode.isBlank()) {
            return null;
        }
        String trimmed = postcode.trim();
        if (!FOUR_DIGITS.matcher(trimmed).matches()) {
            throw new InvalidPostcodeException(postcode);
        }
        String region = OwnerRegion.regionForCity(city);
        if (region != null) {
            int[] range = OwnerRegion.rangeForRegion(region);
            int value = Integer.parseInt(trimmed);
            if (value < range[0] || value > range[1]) {
                throw new InvalidPostcodeException(postcode);
            }
        }
        return trimmed;
    }
}
===== OwnerRegion =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Map;

/**
 * The single source of truth for an owner's canonical region, derived from the postcode and city. A
 * region is a short code (NSW, VIC, QLD) fixed by two lookup tables: the inclusive 4-digit postcode
 * range per region, and the city-to-region fallback used when the postcode yields nothing.
 *
 * <p>{@link #fromPostcode} answers the region for a postcode alone (or {@code null}) and is the source
 * of the REGION component of an owner's {@code customerCode}; {@link #regionOf} reads that component
 * back out of a {@code customerCode}, which is how a whole owner resolves to a locality.
 */
public final class OwnerRegion {

    /** City -> canonical region, from the fixed city-to-region table. */
    private static final Map<String, String> CITY_REGION = Map.of(
            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");

    /** Region -> inclusive 4-digit postcode range {low, high}. */
    private static final Map<String, int[]> REGION_RANGE = Map.of(
            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});

    /** Region -> IANA timezone name, from the fixed region-to-timezone table. */
    private static final Map<String, String> REGION_TIMEZONE = Map.of(
            "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");

    private OwnerRegion() {
    }

    /** The canonical region for {@code city} from the fixed city-to-region table, or {@code null}. */
    static String regionForCity(String city) {
        return city == null ? null : CITY_REGION.get(city);
    }

    /** The inclusive 4-digit postcode range {low, high} for {@code region}, or {@code null}. */
    static int[] rangeForRegion(String region) {
        return REGION_RANGE.get(region);
    }

    /**
     * The region whose fixed range contains {@code postcode} (NSW 2000-2099, VIC 3000-3099,
     * QLD 4000-4099), or {@code null} when the postcode is absent, non-numeric, or in no known range.
     */
    public static String fromPostcode(String postcode) {
        if (postcode == null || postcode.isBlank()) {
            return null;
        }
        int value;
        try {
            value = Integer.parseInt(postcode.trim());
        }
        catch (NumberFormatException ex) {
            return null;
        }
        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
            int[] range = entry.getValue();
            if (value >= range[0] && value <= range[1]) {
                return entry.getKey();
            }
        }
        return null;
    }

    /**
     * The REGION component of a {@code customerCode} ({@code <REGION>-<HASH8>}) — the owner's locality.
     * Now that identity is region-and-hash, the locality is read straight off the assigned code rather
     * than recomputed, so it always matches the code. {@code UNKNOWN} when the code is absent or has no
     * region component.
     */
    public static String regionOf(String customerCode) {
        if (customerCode == null) {
            return "UNKNOWN";
        }
        int dash = customerCode.indexOf('-');
        return dash < 0 ? "UNKNOWN" : customerCode.substring(0, dash);
    }

    /**
     * The IANA timezone name for the owner's region, resolved from the REGION component of the
     * {@code customerCode} through the fixed region-to-timezone table (NSW -> Australia/Sydney,
     * VIC -> Australia/Melbourne, QLD -> Australia/Brisbane). {@code null} when the region is
     * absent or unknown.
     */
    public static String timezoneOf(String customerCode) {
        return REGION_TIMEZONE.get(regionOf(customerCode));
    }
}
===== AssignHouseholdId =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns the owner's deterministic {@code householdId} — the first 12 hex characters of SHA-256 over
 * the normalized lastName and postcode (see {@link OwnerIdentity#deriveHouseholdId}). Because the id
 * is a pure function of (lastName, postcode), every owner that shares a lastName and postcode resolves
 * to the same value automatically, with no back-filling and regardless of creation order. It also
 * records {@code householdSize} — the number of owners that share this household after the create
 * (the existing members with the same computed householdId, plus this new owner). Runs before
 * {@link SaveOwner}, so {@link OwnerRepository#findAll()} returns only the owners that predate this
 * create.
 */
public class AssignHouseholdId {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String householdId = OwnerIdentity.deriveHouseholdId(
                OwnerIdentity.normalizeName(owner.getLastName()), owner.getPostcode());
        owner.setHouseholdId(householdId);

        // Count the existing members of this household (same computed householdId) plus this owner.
        int size = 1;
        for (Owner existing : ownerRepository.findAll()) {
            String existingHousehold = OwnerIdentity.deriveHouseholdId(
                    OwnerIdentity.normalizeName(existing.getLastName()), existing.getPostcode());
            if (householdId.equals(existingHousehold)) {
                size++;
            }
        }
        owner.setHouseholdSize(size);
    }
}

